import base64

def base64_decode_raw(encoded_str: str):
    encoded_str = encoded_str.replace('-', '+').replace('_', '/')
    padding = 4 - len(encoded_str) % 4
    if padding != 4:
        encoded_str += '=' * padding
    byte_data = base64.b64decode(encoded_str)
    return byte_data

if __name__ == "__main__":
    b64_text = ""
    raw_bytes = base64_decode_raw(b64_text)
    print("原始字节:", raw_bytes)
    

